 8: - name: Fail if required mautrix-meta-messenger settings not defined
 9:   ansible.builtin.fail:
10:     msg: >-
11:       You need to define a required configuration setting (`{{ item.name }}`).
12:   when: "item.when | bool and lookup('vars', item.name, default='') | string | length == 0"
13:   with_items:
14:     - {'name': 'matrix_bridge_mautrix_meta_messenger_appservice_token', when: true}
15:     - {'name': 'matrix_bridge_mautrix_meta_messenger_homeserver_token', when: true}
16:     - {'name': 'matrix_bridge_mautrix_meta_messenger_container_network', when: true}
17:     - {'name': 'matrix_bridge_mautrix_meta_messenger_homeserver_address', when: true}
18:     - {'name': 'matrix_bridge_mautrix_meta_messenger_database_hostname', when: "{{ matrix_bridge_mautrix_meta_messenger_database_engine == 'postgres' }}"}
19:     - {'name': 'matrix_bridge_mautrix_meta_messenger_database_password', when: "{{ matrix_bridge_mautrix_meta_messenger_database_engine == 'postgres' }}"}
